package care.tend.task;
import care.tend.common.CurrentUser;import care.tend.item.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/tasks")public class TaskProgressController{private final JdbcTemplate jdbc;private final LifeItemRepository items;public TaskProgressController(JdbcTemplate jdbc,LifeItemRepository items){this.jdbc=jdbc;this.items=items;}public record Request(@NotNull LocalDate newDate,String reason,String initiationStage){}public record Entry(UUID id,LocalDate previousDate,LocalDate newDate,String reason,String initiationStage,Instant createdAt){}
 @PostMapping("/{id}/postpone")@Transactional Entry postpone(@PathVariable UUID id,@Valid@RequestBody Request r){var uid=CurrentUser.id();var task=items.findByIdAndUserId(id,uid).filter(i->i.type==LifeItem.Type.TASK).orElseThrow();var entry=jdbc.queryForObject("insert into task_postponement(user_id,task_id,previous_date,new_date,reason,initiation_stage) values (?,?,?,?,?,?) returning id,previous_date,new_date,reason,initiation_stage,created_at",(rs,n)->new Entry(rs.getObject(1,UUID.class),rs.getObject(2,LocalDate.class),rs.getObject(3,LocalDate.class),rs.getString(4),rs.getString(5),rs.getTimestamp(6).toInstant()),uid,id,task.scheduledDate,r.newDate(),r.reason(),r.initiationStage());task.scheduledDate=r.newDate();items.save(task);return entry;}
 @GetMapping("/{id}/postponements")List<Entry>history(@PathVariable UUID id){var uid=CurrentUser.id();items.findByIdAndUserId(id,uid).filter(i->i.type==LifeItem.Type.TASK).orElseThrow();return jdbc.query("select id,previous_date,new_date,reason,initiation_stage,created_at from task_postponement where user_id=? and task_id=? order by created_at desc",(rs,n)->new Entry(rs.getObject(1,UUID.class),rs.getObject(2,LocalDate.class),rs.getObject(3,LocalDate.class),rs.getString(4),rs.getString(5),rs.getTimestamp(6).toInstant()),uid,id);}}
